import {rigMarkup} from './rig.js';
import {Combat3D} from './combat3d.js';
import './interaction-polish.js';
import{MOVES,FOES,BASIC,newRun,intent,enemyPlan,distance,migrate,unavailable,act,reward,buy,next}from './engine.mjs';
const app=document.querySelector('#app');let s=null,screen='start',replaceMode=false,sound=false,busy=false,ctx;const director=new Combat3D(()=>sound);const KEY='arena-heir-v1';let saved;try{saved=JSON.parse(localStorage.getItem(KEY));if(!saved||saved.version!==1||!Number.isInteger(saved.round)||saved.round<0||saved.round>6||!Array.isArray(saved.moves)||saved.moves.some(m=>!MOVES[m])||!['battle','reward','camp','won','lost'].includes(saved.stage)||!Number.isFinite(saved.hp))saved=null;}catch{saved=null;}if(saved)migrate(saved);
sound=true;
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));saved=structuredClone(s);}catch{}}
function tone(win=false){if(!sound)return;try{ctx??=new AudioContext();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type='triangle';o.frequency.setValueAtTime(win?440:150,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(win?880:60,ctx.currentTime+.15);g.gain.setValueAtTime(.08,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.22);o.start();o.stop(ctx.currentTime+.23);}catch{}}
const char=(i,cls='')=>`<div class="character ${cls}" style="background-position:${(i%3)*50}% ${Math.floor(i/3)*100}%" aria-hidden="true"></div>`;
function header(){return `<header><div class="brand">ARENA <span>HEIR</span></div><div class="tools"><button class="quiet" data-do="help">How to play</button><button class="quiet" data-do="sound" aria-pressed="${sound}">Sound ${sound?'on':'off'}</button>${s?'<button class="quiet" data-do="exit">Save & exit</button>':''}</div></header>`;}
function render(){director.dispose();app.innerHTML=`<div class="wrap">${header()}${screen==='start'?start():s.stage==='battle'?battle():s.stage==='reward'?rewards():s.stage==='camp'?camp():end()}<div class="footerline"><span>Free to play · No account · No ads</span><span>Arena Heir · Duel edition · Progress saved on this device</span></div></div>`;director.mount();}
function start(){return `<section class="intro"><div class="intro-copy"><div class="eyebrow">A gladiator roguelite</div><h1 class="title">Defeat them.<br><span style="color:var(--gold)">Become more.</span></h1><p class="muted">Seven rivals. Three stolen moves.<br>Build your fighter from the champions you defeat.</p><label class="field">Your gladiator's name<input id="name" maxlength="18" placeholder="Choose a name" value="${esc(saved?.name||'')}" autocomplete="off"></label><button class="primary" data-do="start">Enter the arena</button> ${saved&&!['lost','won'].includes(saved.stage)?'<button class="quiet" data-do="resume">Continue run</button>':''}<div class="features"><span>◈ Turn-based duels</span><span>✦ Claim enemy abilities</span><span>♛ Defeat the emperor</span></div></div>${char(0,'intro-art')}</section>`;}
function progress(){return `<div class="topline"><div><div class="eyebrow">The seven gates</div><h1>${esc(s.name)}'s ascent</h1></div><div class="coins">${s.gold} gold</div></div><div class="steps" aria-label="Gate ${s.round+1} of 7">${FOES.map((_,i)=>`<div class="step ${i<=s.round?'done':''}"></div>`).join('')}</div>`;}
function fighter(enemy){const f=FOES[s.round],hp=enemy?s.foeHp:s.hp,max=enemy?f.hp:s.maxHp;return `<div class="fighter ${enemy?'enemy':'player'}" style="--tile:${enemy?s.enemyPos:s.playerPos}"><div class="fighter-info"><div class="name-row"><span>${esc(enemy?f.name:s.name)}</span><span>${hp}/${max}</span></div><div class="health" role="progressbar" aria-label="${enemy?'Rival':'Your'} health" aria-valuenow="${hp}" aria-valuemin="0" aria-valuemax="${max}"><div style="width:${hp/max*100}%"></div></div><div class="stats">${enemy?`${f.title} · ${f.armor} armor`:`+${s.weapon} weapon · ${s.armor} armor${s.bonus?` · +${s.bonus} next attack`:''}`}</div></div><div class="actor" data-side="${enemy?'enemy':'player'}"><div class="actor-shadow"></div><div class="sprite-facing"><div class="combat-sprite articulated" aria-hidden="true">${rigMarkup()}</div></div></div></div>`;}
function intentText(){const[t,n]=enemyPlan(s);return t==='approach'?['Rival will advance','Too far to strike. They can move up to 2 spaces. Your move may change their response.']:t==='attack'?['Incoming strike',`${n} damage before armor. Guard absorbs up to 12.`]:t==='guard'?['Rival is guarding',`Blocks ${n} damage per hit. No attack this turn.`]:t==='charge'?['Rival is winding up','No attack this turn. Prepare for a heavy blow.']:t==='double'?['Incoming twin strike',`Two hits of ${n}. Armor applies to each hit.`]:t==='drain'?['Incoming life drain',`${n} damage. Your rival heals if the hit lands.`]:['Incoming poisoned blade',`${n} damage. Fully block it to prevent poison.`];}
const shortNames={attack:'Strike',power:'Crush',guard:'Block',dodge:'Dodge',forward:'Leap in',back:'Leap back',rest:'Breathe'};
function forecast(id){const copy=structuredClone(s),events=[];if(!act(copy,id,events))return '';const dealt=events.filter(e=>e.actor==='player'&&e.type==='hit').reduce((n,e)=>n+e.damage,0),taken=events.filter(e=>e.actor==='enemy'&&e.type==='hit').reduce((n,e)=>n+e.damage,0);return `${dealt?`${dealt} damage · `:''}${taken?`Take ${taken}`:'No hit taken'}${copy.bonus?` · Next hit +${copy.bonus}`:''}`;}
function button(id,name,icon,desc){const why=unavailable(s,id),preview=why||forecast(id),cost=BASIC[id]?.cost||0,damage=preview.match(/^(\d+) damage/);return `<button class="duel-action action-${id} ${MOVES[id]?'special':''}" data-action="${id}" data-preview="${esc(desc+' '+preview)}" aria-label="${esc((shortNames[id]||name)+'. '+desc+' '+preview)}" ${why?'disabled':''}><span class="action-icon" aria-hidden="true">${icon}</span><strong>${shortNames[id]||name}</strong><small>${why|| (damage?`${damage[1]} damage`:id==='guard'?'Block 12':id==='dodge'?'Evade + counter':id==='rest'?'+3 energy':preview.match(/Take \d+/)?.[0]||'No hit taken')}</small><span class="action-cost">${cost?`${cost} ⚡`:MOVES[id]?`${MOVES[id].cd}T`:'FREE'}</span></button>`;}
function battle(){const [a,b]=intentText();return `<div class="battle-shell"><div class="duel-ribbon"><h1>Gate ${s.round+1} <span>/ 7</span></h1><span>YOUR DUEL</span><strong>${s.gold} gold</strong></div><section class="arena" aria-label="3D gladiator arena" data-round="${s.round}"><canvas class="arena-life" aria-hidden="true"></canvas>${fighter(false)}${fighter(true)}<div class="rival-intent"><span>NEXT MOVE</span><strong>${a}</strong><small>${b}</small></div><div class="combat-caption" role="status" aria-live="polite"></div><div class="combat-fx" aria-hidden="true"></div><div class="arena-distance">${distance(s)===1?'IN REACH':`${distance(s)} spaces apart`}</div></section><div class="duel-dock"><div class="duel-turn"><strong>${s.bonus?`NEXT HIT +${s.bonus}`:'YOUR MOVE'}</strong><span>Turn ${s.turn+1} · Take your time</span><div class="duel-energy"><span>Energy <b id="energy-value">${s.energy}</b>/6</span><span class="energy-pips" aria-hidden="true">${Array.from({length:6},(_,i)=>`<i class="${i<s.energy?'lit':''}"></i>`).join('')}</span></div></div>${s.poison?'<p class="danger">Poisoned · 3 damage after your turn</p>':''}<div class="actions duel-controls">${Object.entries(BASIC).map(([id,m])=>button(id,m.name,m.icon,m.desc)).join('')}</div>${s.moves.length?`<div class="actions claimed-controls">${s.moves.map(id=>button(id,MOVES[id].name,MOVES[id].icon,MOVES[id].desc)).join('')}</div>`:''}<p class="move-preview" id="move-preview">${distance(s)>1?'Close the gap to attack. Leaping in may trigger a strike.':'Read their move. Make yours count.'}</p><details class="combat-history"><summary>${esc(s.log.at(-1)||'Battle log')}</summary><div class="log">${s.log.map(l=>`<div>${esc(l)}</div>`).join('')}</div></details></div></div>`;}
function rewards(){const f=FOES[s.round],m=MOVES[f.move];return `${progress()}<section class="panel"><div class="eyebrow">Gate ${s.round+1} cleared</div><h1>Their power. Your choice.</h1><p class="muted">${f.name} falls. You earned ${18+s.round*3} gold.<br>Choose one reward before entering the armory.</p>${replaceMode?`<div class="notice">Your three move slots are full. Choose a move to replace with <strong>${m.name}</strong>.</div><div class="cards">${s.moves.map(id=>`<button class="card" data-replace="${id}"><strong>${MOVES[id].name}</strong><p>${MOVES[id].desc}</p><span class="eyebrow">Replace this move</span></button>`).join('')}</div><button class="quiet" data-do="cancel-replace">Back to rewards</button>`:`<div class="cards"><button class="card selected" data-reward="move"><span class="symbol">${m.icon}</span><strong>Claim ${m.name}</strong><p>${m.desc}</p><span class="eyebrow">${s.moves.length<3?'Learn their signature move':'Choose a move to replace'}</span></button><button class="card" data-reward="heal"><span class="symbol">♥</span><strong>Recover 26 health</strong><p>Current health: ${s.hp}/${s.maxHp}. Keep your existing moves.</p></button><button class="card" data-reward="gold"><span class="symbol">✦</span><strong>Take 25 extra gold</strong><p>Invest in stronger equipment at the armory.</p></button></div>`}</section>`;}
function camp(){return `${progress()}<section class="panel"><div class="eyebrow">Between battles</div><h1>A little steel. A second wind.</h1><p class="muted">Health ${s.hp}/${s.maxHp} · Weapon +${s.weapon} · Armor ${s.armor}<br>You recover 10 health for free when you enter the next gate.</p><div class="cards">${[['weapon','⚔','Sharpen weapon','+2 damage on every hit.',30],['armor','⬡','Reinforce armor','Reduce each incoming hit by 1.',30],['heal','♥','Visit the healer','Recover 25 health.',20]].map(([id,ic,n,d,c])=>`<button class="card" data-buy="${id}" ${s.gold<c||(id==='heal'&&s.hp===s.maxHp)?'disabled':''}><span class="symbol">${ic}</span><strong>${n}</strong><p>${d}</p><span class="eyebrow">${c} gold</span></button>`).join('')}</div><div class="notice">Next rival: <strong>${FOES[s.round+1].name}</strong> · ${FOES[s.round+1].title}</div><button class="primary" data-do="next">Enter gate ${s.round+2} →</button></section>`;}
function end(){const won=s.stage==='won';return `<section class="panel"><div class="eyebrow">${won?'The arena has a new ruler':'Your run has ended'}</div><h1>${won?'The crown is yours.':'Fallen. Not forgotten.'}</h1><div class="end-score">${won?7:s.round}<span style="font-size:32px;color:#b9b6b1"> / 7 gates</span></div><p class="muted">${won?'You turned your rivals’ strengths into your own. Try a different combination on your next run.':`${FOES[s.round].name} ended your ascent. Watch their intent and save your guard for the dangerous turns.`}</p><div class="log">${s.log.map(l=>`<div>${esc(l)}</div>`).join('')}</div><div class="section-label">Your claimed moves</div><p>${s.moves.map(id=>MOVES[id].name).join(' · ')||'No moves claimed yet'}</p><button class="primary" data-do="restart">One more run</button><button class="quiet" data-do="exit">Main menu</button></section>`;}
function help(){const d=document.createElement('dialog');d.innerHTML='<h2>Win their moves. Build your legend.</h2><p>Read the rival’s next action above your buttons. Strike when they wind up; guard against dangerous attacks. Guard lasts one turn. Fully blocking an attack gives your next hit +2 damage.</p><p>After a win, choose a stolen move, healing, or gold. Equip up to three stolen moves. Special moves need other turns to recharge.</p><p>Visit the armory between gates. Weapon upgrades improve every hit; armor reduces every incoming hit. Free recovery restores 10 health before each new rival.</p><p>Defeat all seven rivals to win. Your run saves automatically on this device. Keys 1–7 select basic actions. Leap forward or back to change distance. Melee attacks need adjacent positions; Blood oath and Viper bite reach 3 spaces. A dodge avoids only the first hit. Recover restores energy but leaves you exposed.</p><button class="primary">Back to the arena</button>';document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();}
app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled||busy)return;const d=b.dataset;if(d.action){if(s.stage!=='battle')return;busy=true;const after=structuredClone(s),events=[];if(!act(after,d.action,events)){busy=false;return;}document.querySelectorAll('[data-action]').forEach(el=>el.disabled=true);try{await director.play(events,s);}catch(error){console.error('Combat playback recovered',error);}finally{s=after;save();busy=false;render();if(s.stage!=='battle')tone(true);}return;}if(d.reward){if(d.reward==='move'&&s.moves.length>=3)replaceMode=true;else reward(s,d.reward);save();render();return;}if(d.replace){reward(s,'move',d.replace);replaceMode=false;save();render();return;}if(d.buy){buy(s,d.buy);save();render();return;}if(d.do==='sound'){sound=!sound;if(sound)tone(true);render();return;}if(d.do==='help'){help();return;}if(d.do==='start'){const name=document.querySelector('#name').value.trim()||'The Challenger';if(saved&&!['won','lost'].includes(saved.stage)){const dia=document.createElement('dialog');dia.innerHTML='<h2>Start a new run?</h2><p>Your saved run will be replaced.</p><button class="primary" id="yes">Start new run</button> <button class="quiet" id="no">Keep saved run</button>';document.body.append(dia);dia.querySelector('#yes').onclick=()=>{s=newRun(name);screen='game';save();dia.close();render();};dia.querySelector('#no').onclick=()=>dia.close();dia.onclose=()=>dia.remove();dia.showModal();return;}s=newRun(name);screen='game';save();}if(d.do==='resume'){s=structuredClone(saved);screen='game';}if(d.do==='restart'){s=newRun(s.name);screen='game';save();}if(d.do==='exit'){if(s)save();s=null;screen='start';}if(d.do==='next'){next(s);save();}if(d.do==='cancel-replace')replaceMode=false;render();});
for(const event of ['pointerover','focusin'])app.addEventListener(event,e=>{const button=e.target.closest('[data-preview]');if(button&&!busy){const preview=document.querySelector('#move-preview');if(preview)preview.textContent=button.dataset.preview;}});
document.addEventListener('keydown',e=>{if(e.target.matches('input')||document.querySelector('dialog[open]')||!s||s.stage!=='battle'||e.repeat)return;const n=Number(e.key);if(n>=1&&n<=7)document.querySelectorAll('[data-action]')[n-1]?.click();});render();
